આપેલ છે કે, ABCD સમાંતરબાજુ ચતુષ્કોણ છે. AC અને BD તેના બે વિકર્ણો છે. આપણે સદિશો \vec{AB} અને \vec{AC} ને \vec{AD} અને \vec{BD} ના સ્વરૂપમાં દર્શાવવાના છે અને બતાવવાનું છે કે,
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ અને } \vec{AC} - \vec{BD} = 2\vec{AB}.

\text{ત્રિકોણ } \Delta ABD \text{ માં,}
\vec{AD} = \vec{AB} + \vec{BD} \text{ [ત્રિકોણનો નિયમ]}
\therefore \vec{AB} = \vec{AD} - \vec{BD} \text{.............(i)}
\text{ફરીથી ત્રિકોણ ACD માં, } \vec{AC} = \vec{AD} + \vec{DC} \text{[ત્રિકોણનો નિયમ]}
\text{[કારણ કે, ABCD સમાંતરબાજુ ચતુષ્કોણ છે, તેથી } \vec{DC} = \vec{AB}]
= \vec{AD} + \vec{AD} - \vec{BD} [\because \vec{AB} = \vec{AD} - \vec{BD}]
\therefore \vec{AC} = 2\vec{AD} - \vec{BD} \text{.............(ii)}
\text{હવે, } \vec{AC} + \vec{BD} = 2\vec{AD} - \vec{BD} + \vec{BD}
\text{[(ii) ની બંને બાજુમાં } \vec{BD} \text{ ઉમેરતાં]}
= 2 \vec{AD}
\therefore \vec{AC} + \vec{BD} = 2 \vec{BC} \text{.............(iii)}
\text{[કારણ કે, ABCD સમાંતરબાજુ ચતુષ્કોણ છે, તેથી } \vec{AD} = \vec{BC}]
\text{ફરીથી, } \vec{AC} - \vec{BD} = (2\vec{AD} - \vec{BD}) - \vec{BD} \text{ [(ii) નો ઉપયોગ કરતાં]}
= 2\vec{AD} - 2 \vec{BD} = 2 (\vec{AD} - \vec{BD})
= 2\vec{AB} \text{ [(i) નો ઉપયોગ કરતાં]}
\therefore \vec{AC} - \vec{BD} = 2\vec{AB} \text{.............(iv)}
\text{હવે, સમીકરણ (i), (ii), (iii) અને (iv) પરથી આપણે મેળવીએ છીએ,}
\vec{AB} = \vec{AD} - \vec{BD}
\vec{AC} = 2\vec{AD} - \vec{BD}
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ અને } \vec{AC} - \vec{BD} = 2\vec{AB} \text{ (સાબિત થયું)}

તે દર્શાવવાનું જરૂરી છે કે, } -(\underline{a} + \underline{b}) = -\underline{a} - \underline{b}
\text{હવે, } -(\underline{a} + \underline{b}) = (-1) (\underline{a} + \underline{b})
= (-1) \underline{a} + (-1) \underline{b} \text{ [વિતરણનો નિયમ]}
= -\underline{a} - \underline{b}
\therefore -(\underline{a} + \underline{b}) = -\underline{a} - \underline{b} \text{ (દર્શાવેલ છે)}

\text{ એ દર્શાવવાનું જરૂરી છે કે, } \mathbf{a} + \mathbf{a} = 2\mathbf{a}
\text{હવે, } \mathbf{a} + \mathbf{a} = 1\mathbf{a} + 1\mathbf{a}
\text{[સ્કેલર ગુણાકારના નિયમ મુજબ]}
= (1+1)\mathbf{a} \text{ } [\because (m+n)\mathbf{a} = m\mathbf{a} + n\mathbf{a}]
= 2\mathbf{a}
\therefore \mathbf{a} + \mathbf{a} = 2\mathbf{a} \text{ (સાબિત થયું)}

\text{ દર્શાવવાનું જરૂરી છે કે, } (m-n)\mathbf{a} = m\mathbf{a} - n\mathbf{a}
\text{હવે, } (m-n)\mathbf{a} = \{m + (-n)\}\mathbf{a}
= m\mathbf{a} + (-n)\mathbf{a} \text{ } [\because (m+n)\mathbf{a}=m\mathbf{a} + n\mathbf{a}]
= m\mathbf{a} - n\mathbf{a} \text{ } [\because (-n)\mathbf{a} = -n\mathbf{a}]
\therefore (m-n)\mathbf{a} = m\mathbf{a} - n\mathbf{a} \text{ (દર્શાવેલ)}

bc(b-c) + ca(c-a) + ab(a-b)
= bc(b-c) + c^2a - ca^2 + a^2b - ab^2
= bc(b-c) + a^2b - ca^2 - ab^2 + c^2a
= bc(b-c) + a^2(b-c) - a(b^2-c^2)
= bc(b-c) + a^2(b-c) - a(b+c)(b-c)
= (b-c)\{bc + a^2 - a(b+c)\}
= (b-c)\{bc + a^2 - ab - ac\}
= (b-c)\{bc - ab - ac + a^2\}
= (b-c)\{b(c-a) - a(c-a)\}
= (b-c)(c-a)(b-a)
= -(a-b)(b-c)(c-a)

